<template>
  <main class="work-storage">
    <header><div><h1>工作资料管理</h1><p>查看原粮通报、原粮考勤和制曲上传资料，按需清理过期内容。</p></div><button :disabled="busy" @click="load">刷新</button></header>
    <section class="storage-summary"><div v-for="group in groups" :key="group.key"><span>{{group.label}}</span><strong>{{fileSize(group.bytes)}}</strong><small>{{group.count}} 份资料 · {{group.files}} 个文件</small></div></section>
    <section class="storage-controls"><label>资料类型<el-select v-model="kind" placeholder="全部类型" @change="page=1;load()"><el-option label="全部类型" value=""/><el-option v-for="(label,key) in typeLabels" :key="key" :label="label" :value="key"/></el-select></label><label>最后更新早于<input v-model="cutoff" type="date" :max="yesterday" @change="page=1;load()"/></label><p>只清理所选日期之前、已过保留日期且未被引用的资料。</p></section>
    <p v-if="error" class="storage-error" role="alert">{{error}}</p><p v-if="message" class="storage-message" role="status">{{message}}</p>
    <section class="storage-table-panel"><div class="storage-table-scroll"><table><thead><tr><th>资料 / 类型</th><th>所属车间</th><th>文件 / 占用</th><th>最后更新</th><th>保留截止</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="item in items" :key="`${item.kind}:${item.id}`"><td><b>{{item.title}}</b><small>{{typeLabels[item.kind]}} · #{{item.id}}</small></td><td>{{item.workshopCode==='raw_grain'?'原粮车间':'制曲车间'}}</td><td>{{fileSize(item.bytes)}}<small>{{item.fileCount}} 个文件</small></td><td>{{item.updatedAt}}</td><td><template v-if="['inspection','attendance'].includes(item.kind)"><button class="retention-button" :disabled="busy" @click="setRetention(item)">{{item.retentionUntil||'未设置'}}<el-icon><Edit /></el-icon></button></template><span v-else>按更新时间</span></td><td><span :class="item.eligible?'eligible':'protected'">{{item.eligible?'可清理':item.referenceCount?'仍被记录引用':item.retentionUntil&&item.retentionUntil>=today?'保留期内':'不在清理范围'}}</span></td><td><button class="delete-button" :disabled="busy||!item.eligible" @click="remove(item)">清理</button></td></tr></tbody></table></div><p v-if="!items.length" class="storage-empty">{{busy?'正在读取资料…':'没有此类资料。'}}</p><el-pagination v-if="total>30" v-model:current-page="page" :total="total" :page-size="30" layout="prev,pager,next,total" @current-change="load"/></section>
    <p class="storage-note">原粮通报、考勤导入会连同原文件和对应结果删除。制曲只清理截图或附件，保留工作文字和考评记录。清理会留下管理员操作日志，数据库空间供后续写入复用。</p>
    <details class="storage-audit" @toggle="loadAudit"><summary>最近清理记录</summary><ul><li v-for="entry in audit" :key="entry.id">{{entry.created_at}} · {{entry.title}} · 清理 {{fileSize(entry.released_bytes)}} · 操作人 #{{entry.actor_id}}</li></ul><p v-if="!audit.length">暂无清理记录。</p></details>
    <el-dialog v-model="retentionOpen" title="设置保留截止日期" width="min(440px, calc(100vw - 28px))"><p>{{retentionItem?.title}}</p><label class="retention-field">保留到<input v-model="retentionDate" type="date"/></label><p>日期过后仍需管理员手动清理，不会自动删除。</p><template #footer><el-button @click="retentionOpen=false">取消</el-button><el-button type="primary" :loading="busy" @click="saveRetention">保存</el-button></template></el-dialog>
  </main>
</template>
<script setup>
import {computed,onMounted,ref} from 'vue'
import {ElMessageBox} from 'element-plus'
import {Edit} from '@element-plus/icons-vue'
import {office} from '../api/attendance'
import {fileSize} from '../utils/attendance-display.mjs'
const today=new Date(Date.now()+8*3600000).toISOString().slice(0,10),yesterday=new Date(Date.now()+8*3600000-86400000).toISOString().slice(0,10)
const cutoff=ref(new Date(Date.now()+8*3600000-90*86400000).toISOString().slice(0,10)),kind=ref(''),page=ref(1),items=ref([]),summary=ref([]),total=ref(0),busy=ref(false),error=ref(''),message=ref(''),audit=ref([])
const retentionOpen=ref(false),retentionItem=ref(null),retentionDate=ref('')
const typeLabels={inspection:'原粮检查通报',attendance:'原粮考勤导入',work_photo:'制曲工作截图',task_file:'制曲任务附件'}
const groups=computed(()=>[{key:'inspection',label:'原粮通报',kinds:['inspection']},{key:'attendance',label:'原粮考勤',kinds:['attendance']},{key:'qu',label:'制曲资料',kinds:['work_photo','task_file']}].map(g=>({...g,bytes:summary.value.filter(s=>g.kinds.includes(s.kind)).reduce((n,s)=>n+s.bytes,0),count:summary.value.filter(s=>g.kinds.includes(s.kind)).reduce((n,s)=>n+s.itemCount,0),files:summary.value.filter(s=>g.kinds.includes(s.kind)).reduce((n,s)=>n+s.fileCount,0)})))
async function load(){busy.value=true;error.value='';try{const r=await office.get('/work-storage',{params:{cutoff:cutoff.value,kind:kind.value,page:page.value}});items.value=r.data.items;summary.value=r.data.summary;total.value=r.data.total}catch(e){error.value=e.response?.data?.msg||'资料读取失败'}finally{busy.value=false}}
async function remove(item){
  const scope=['work_photo','task_file'].includes(item.kind)?'只删除此图片附件，工作文字和考评记录保留。':'原始文件、对应结果与相关备注将一并删除。'
  try{await ElMessageBox.confirm(`清理“${item.title}”（${fileSize(item.bytes)}）？${scope}删除后不可恢复。`,'清理过期资料',{type:'warning',confirmButtonText:'确认清理',cancelButtonText:'取消'})}catch{return}
  busy.value=true;try{const r=await office.delete(`/work-storage/${item.kind}/${item.id}`,{data:{cutoff:cutoff.value,revision:item.revision}});message.value=`已清理 ${fileSize(r.data.releasedBytes)} 数据内容。`;if(items.value.length===1&&page.value>1)page.value--;await load();await loadAudit()}catch(e){error.value=e.response?.data?.msg||'清理失败，请刷新后重试'}finally{busy.value=false}
}
function setRetention(item){retentionItem.value=item;retentionDate.value=item.retentionUntil||'';retentionOpen.value=true}
async function saveRetention(){busy.value=true;try{await office.patch(`/work-storage/${retentionItem.value.kind}/${retentionItem.value.id}/retention`,{retentionUntil:retentionDate.value||null,revision:retentionItem.value.revision});retentionOpen.value=false;await load()}finally{busy.value=false}}
async function loadAudit(event){if(event&&!event.target.open)return;try{const r=await office.get('/work-storage/audit');audit.value=r.data}catch{error.value='清理日志读取失败'}}
onMounted(load)
</script>
<style scoped>
.work-storage{max-width:1440px;margin:auto;color:#183047;display:grid;gap:18px;font-size:14px}.work-storage header{display:flex;justify-content:space-between;align-items:center;gap:16px}.work-storage h1{font-size:26px;margin:0 0 8px}.work-storage p{color:#607487;font-size:13px;line-height:1.8;margin:0}.work-storage button{display:inline-flex;align-items:center;gap:6px;min-height:36px;padding:8px 14px;border:1px solid #dee5ed;border-radius:7px;background:white;color:#5b5cab;font:inherit;font-size:13px;cursor:pointer}.work-storage button:disabled{opacity:.4;cursor:default}.storage-summary{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.storage-summary>div{background:white;border:1px solid #dee5ed;border-radius:10px;padding:20px;display:grid;gap:14px}.storage-summary strong{font-size:27px;color:#45468b}.storage-summary small{font-size:12px;color:#8492a6}.storage-controls{display:flex;gap:18px;align-items:end;flex-wrap:wrap}.storage-controls label{display:grid;gap:8px}.storage-controls .el-select{width:220px}.storage-controls input,.retention-field input{padding:8px 12px;border:1px solid #dee5ed;border-radius:6px;background:white;color:#183047;font:inherit;min-height:38px}.storage-controls p{flex:1;padding-bottom:5px}.storage-table-panel{background:white;border:1px solid #dee5ed;border-radius:10px;padding:18px}.storage-table-scroll{overflow:auto}.work-storage table{width:100%;border-collapse:collapse;min-width:1050px;text-align:left;font-size:13px}.work-storage th{background:#f6f7fa;color:#607487;padding:13px;font-weight:600;white-space:nowrap}.work-storage td{padding:16px 13px;border-bottom:1px solid #e8ecf1;vertical-align:middle;line-height:1.5}.work-storage td:first-child{max-width:350px;overflow-wrap:anywhere}.work-storage td small{display:block;margin-top:6px;color:#8492a6;font-size:12px}.work-storage .retention-button{border:0;background:transparent;padding:0;min-height:28px}.work-storage .delete-button{color:#bd2438;border-color:#eccbd0}.eligible{color:#258161;background:#eaf7f3;padding:4px 7px;border-radius:5px;white-space:nowrap}.protected{color:#8492a6;white-space:nowrap}.work-storage .storage-error{color:#bd2438;background:#fff1f2;padding:12px;border-radius:7px}.work-storage .storage-message{color:#258161;background:#eaf7f3;padding:12px;border-radius:7px}.storage-table-panel .el-pagination{justify-content:flex-end;margin-top:18px}.work-storage .storage-empty{text-align:center;padding:40px}.storage-note{padding:0 2px}.storage-audit{background:white;border:1px solid #dee5ed;padding:16px;border-radius:10px;font-size:13px;color:#607487}.storage-audit summary{cursor:pointer;color:#183047}.storage-audit li{line-height:1.8;margin-top:8px}.retention-field{display:grid;gap:8px;margin:18px 0}.work-storage button:focus-visible,.work-storage input:focus-visible{outline:2px solid #5b5cab;outline-offset:2px}@media(max-width:650px){.storage-summary{gap:8px}.storage-summary>div{padding:13px;gap:10px}.storage-summary strong{font-size:19px}.storage-summary span{font-size:13px}.work-storage h1{font-size:22px}.storage-controls label{width:100%}.storage-controls .el-select{width:100%}.storage-controls p{flex-basis:100%}.storage-table-panel{padding:10px}}
</style>
